 1→/**
 2→ * @cipherbox/crypto - ECIES Key Re-Wrapping
 3→ *
 4→ * Re-wraps a key from one recipient to another using ECIES.
 5→ * Used for user-to-user sharing: owner unwraps their key and
 6→ * re-wraps it with the recipient's public key.
 7→ *
 8→ * The plaintext key is zeroed from memory after re-wrapping.
 9→ */
10→
11→import { unwrapKey } from './decrypt';
12→import { wrapKey } from './encrypt';
13→import { CryptoError } from '../types';
14→
15→/**
16→ * Re-wrap a key from owner encryption to recipient encryption.
17→ *
18→ * Unwraps a key using the owner's private key, then re-wraps it
19→ * with the recipient's public key. The plaintext key is zeroed
20→ * from memory after re-wrapping.
21→ *
22→ * @param ownerWrappedKey - ECIES ciphertext wrapped with owner's public key
23→ * @param ownerPrivateKey - 32-byte secp256k1 private key of the owner
24→ * @param recipientPublicKey - 65-byte uncompressed secp256k1 public key of the recipient
25→ * @returns Key re-wrapped for the recipient
26→ * @throws CryptoError with code 'KEY_REWRAP_FAILED' on any failure
27→ */
28→export async function reWrapKey(
29→  ownerWrappedKey: Uint8Array,
30→  ownerPrivateKey: Uint8Array,
31→  recipientPublicKey: Uint8Array
32→): Promise<Uint8Array> {
33→  let plainKey: Uint8Array | null = null;
34→
35→  try {
36→    // 1. Unwrap with owner's private key
37→    plainKey = await unwrapKey(ownerWrappedKey, ownerPrivateKey);
38→
39→    // 2. Re-wrap with recipient's public key
40→    const reWrapped = await wrapKey(plainKey, recipientPublicKey);
41→
42→    // 3. Zero the plaintext key
43→    plainKey.fill(0);
44→
45→    return reWrapped;
46→  } catch {
47→    // Zero the plaintext key if it was successfully unwrapped
48→    if (plainKey) {
49→      plainKey.fill(0);
50→    }
51→
52→    // Generic error to prevent information leakage
53→    throw new CryptoError('Key re-wrapping failed', 'KEY_REWRAP_FAILED');
54→  }
55→}
