 13→/**
 14→ * Build a breadcrumb-style path string for a folder by walking up the tree.
 15→ * e.g., "My Vault / Documents / Reports"
 16→ */
 17→function buildFolderPath(folderId: string): string {
 18→  const folders = useFolderStore.getState().folders;
 19→  const parts: string[] = [];
 20→  let currentId: string | null = folderId;
 21→
 22→  while (currentId !== null) {
 23→    const folder: FolderNode | undefined = folders[currentId];
 24→    if (!folder) break;
 25→    // Stop before including the root node (its name is already the "My Vault" prefix)
 26→    if (folder.parentId === null) break;
 27→    parts.unshift(folder.name);
 28→    currentId = folder.parentId;
 29→  }
 30→
 31→  return parts.length > 0 ? `My Vault / ${parts.join(' / ')}` : 'My Vault';
 32→}
 33→
 34→/**
 35→ * Get the parent folder node from the store, resolving 'root' via vault state.
 36→ */
 37→function getParentFolder(parentId: string): FolderNode | null {
 38→  const freshState = useFolderStore.getState();
 39→  return parentId === 'root'
 40→    ? getRootFolderState(useVaultStore.getState(), freshState.folders)
 41→    : freshState.folders[parentId];
 42→}
