 66→   */
 67→  const handleCreate = useCallback(
 68→    async (name: string, parentId: string | null): Promise<{ ipnsName: string }> => {
 69→      setState({ isLoading: true, error: null });
 70→      try {
 71→        const folders = useFolderStore.getState().folders;
 72→
 73→        // Validate depth limit before creating (FOLD-03)
 74→        const parentDepth = folderService.getDepth(parentId, folders);
 75→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 76→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 77→        }
 78→
 79→        // Resolve parent folder
 80→        const actualParentId = parentId ?? 'root';
 81→        const parentFolder = getParentFolder(actualParentId);
 82→        if (!parentFolder) {
 83→          throw new Error('Parent folder not found or vault not initialized');
 84→        }
 85→
 86→        // Ensure parent is registered in SDK's FolderTree
 87→        ensureFolderRegistered(parentFolder);
 88→
 89→        // Create folder via SDK (handles key gen, metadata update, IPNS publish)
 90→        const client = getSdkClient();
 91→        const result = await client.createFolder(parentFolder.ipnsName, name);
