183→/**
184→ * Ensure sent shares cache is fresh (fetched within last 30s).
185→ * Returns the current sent shares array.
186→ */
187→async function ensureFreshSentShares(): Promise<SentShare[]> {
188→  const store = useShareStore.getState();
189→  if (store.lastSentFetchedAt && Date.now() - store.lastSentFetchedAt < 30_000) {
190→    return store.sentShares;
191→  }
192→  // Re-wrapping needs the full set — paginate through all pages
193→  const allShares = await fetchAllSentShares();
194→  useShareStore.getState().setSentShares(allShares);
195→  return allShares;
196→}
197→
198→/**
199→ * Fetch ALL sent shares by paginating through the API.
200→ * The API enforces a max limit of 100 per page.
201→ */
202→async function fetchAllSentShares(): Promise<SentShare[]> {
203→  const pageSize = 100;
204→  let offset = 0;
205→  const allShares: SentShare[] = [];
206→
207→  while (true) {
208→    const { shares, total } = await fetchSentShares(pageSize, offset);
209→    allShares.push(...shares);
210→    offset += shares.length;
211→    if (offset >= total || shares.length === 0) break;
212→  }
213→
214→  return allShares;
215→}
