260→/**
261→ * After adding a file or subfolder to a shared folder, re-wrap the new key
262→ * for all existing share recipients.
263→ *
264→ * This is a fire-and-forget operation -- failures are logged but don't block
265→ * the primary upload/create flow.
266→ *
267→ * IMPORTANT: Callers are responsible for zeroing `newItems[*].plaintextKey`
268→ * after this function completes. This function does NOT zero the keys because
269→ * some callers (e.g., subfolder creation) keep the key alive in the store.
270→ * Use a `finally` block to ensure zeroing even on errors.
271→ *
272→ * @param params.folderIpnsName - IPNS name of the folder being modified
273→ * @param params.folders - Current folder tree from the store
274→ * @param params.currentFolderId - ID of the current folder in the tree
275→ * @param params.newItems - New items whose keys need re-wrapping
276→ */
277→export async function reWrapForRecipients(params: {
278→  folderIpnsName: string;
279→  folders: Record<string, FolderNode>;
280→  currentFolderId: string | null;
281→  newItems: Array<{
282→    keyType: 'file' | 'folder';
283→    itemId: string;
284→    plaintextKey: Uint8Array;
285→  }>;
286→}): Promise<{ failedRecipients: string[] }> {
287→  const coveringShares = await findCoveringShares(
288→    params.folderIpnsName,
289→    params.folders,
290→    params.currentFolderId
291→  );
292→
293→  if (coveringShares.length === 0) return { failedRecipients: [] };
294→
295→  const failedRecipients: string[] = [];
296→
297→  // For each share recipient, re-wrap all new item keys
298→  for (const share of coveringShares) {
299→    try {
300→      const recipientPubKey = hexToBytes(
301→        share.recipientPublicKey.startsWith('0x')
302→          ? share.recipientPublicKey.slice(2)
303→          : share.recipientPublicKey
304→      );
305→
306→      const wrappedKeys: Array<{
307→        keyType: 'file' | 'folder';
308→        itemId: string;
309→        encryptedKey: string;
310→      }> = [];
311→
312→      for (const item of params.newItems) {
313→        const wrapped = await wrapKey(item.plaintextKey, recipientPubKey);
314→        wrappedKeys.push({
315→          keyType: item.keyType,
316→          itemId: item.itemId,
317→          encryptedKey: bytesToHex(wrapped),
318→        });
319→      }
320→
321→      // Add the wrapped keys to this share via API
322→      await addShareKeys(share.shareId, wrappedKeys);
323→    } catch (err) {
324→      console.warn(
325→        `[share] Failed to re-wrap keys for recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
326→        err
327→      );
328→      failedRecipients.push(share.recipientPublicKey);
329→    }
330→  }
331→
332→  return { failedRecipients };
333→}
