339→/** A revoked share pending key rotation. */
340→export type PendingRotation = {
341→  shareId: string;
342→  recipientPublicKey: string;
343→  itemType: 'folder' | 'file';
344→  ipnsName: string;
345→  itemName: string;
346→  revokedAt: string;
347→};
