349→/**
350→ * Fetch revoked shares that are pending key rotation from the server.
351→ * These are shares where revokedAt is set but the share has not been hard-deleted.
352→ */
353→export async function fetchPendingRotations(): Promise<PendingRotation[]> {
354→  const response = await sharesControllerGetPendingRotations();
355→
356→  return response.map((r) => ({
357→    shareId: r.shareId,
358→    recipientPublicKey: r.recipientPublicKey,
359→    itemType: r.itemType as 'folder' | 'file',
360→    ipnsName: r.ipnsName,
361→    itemName: r.itemName,
362→    revokedAt: String(r.revokedAt),
363→  }));
364→}
365→
366→/**
367→ * Check if a folder has pending rotations (revoked shares awaiting key rotation).
368→ * Called before any folder modification.
369→ *
370→ * @param folderIpnsName - IPNS name of the folder being modified
371→ * @returns true if there are revoked shares for this folder that need rotation
372→ */
373→export async function checkPendingRotation(folderIpnsName: string): Promise<boolean> {
374→  const pendingRotations = await fetchPendingRotations();
375→  return pendingRotations.some((r) => r.ipnsName === folderIpnsName);
376→}
377→
378→/**
379→ * Update the encrypted key on a share record after lazy key rotation.
380→ * Re-wraps the new folder key for a remaining (non-revoked) recipient.
381→ */
382→export async function updateShareKey(shareId: string, encryptedKey: string): Promise<void> {
383→  await sharesControllerUpdateShareEncryptedKey(shareId, { encryptedKey });
384→}
385→
386→/**
387→ * Hard-delete a revoked share after rotation is complete.
388→ */
389→export async function completeShareRotation(shareId: string): Promise<void> {
390→  await sharesControllerCompleteRotation(shareId);
391→}
392→
393→/**
394→ * Execute lazy key rotation for a folder.
395→ * Called when a folder modification is about to happen and pending rotations exist.
396→ *
397→ * Protocol:
398→ * 1. Generate new random folderKey
399→ * 2. Re-wrap new folderKey for each REMAINING (non-revoked) active recipient
400→ * 3. Update remaining shares with the new encrypted key
401→ * 4. Hard-delete revoked share records (rotation complete)
402→ * 5. Invalidate share cache
403→ *
404→ * NOTE: The actual folder metadata re-encryption (decrypt with old key, re-encrypt
405→ * with new key, re-publish IPNS) is handled by the caller (folder.service.ts)
406→ * since it has access to the folder's IPNS private key and publishing infrastructure.
407→ *
408→ * @returns The new folderKey for the caller to use
409→ */
410→export async function executeLazyRotation(params: {
411→  folderIpnsName: string;
412→  oldFolderKey: Uint8Array;
413→  ownerPublicKey: Uint8Array;
414→}): Promise<{ newFolderKey: Uint8Array }> {
415→  // 1. Generate new random 32-byte folderKey
416→  const newFolderKey = generateRandomBytes(32);
417→
418→  // 2. Fetch pending rotations and active shares for this folder
419→  const [pendingRotations, activeSentShares] = await Promise.all([
420→    fetchPendingRotations(),
421→    getSentSharesForItem(params.folderIpnsName),
422→  ]);
423→
424→  const revokedForFolder = pendingRotations.filter((r) => r.ipnsName === params.folderIpnsName);
425→  const revokedShareIds = new Set(revokedForFolder.map((r) => r.shareId));
426→
427→  // Active shares that are NOT revoked -- these recipients keep access
428→  const remainingShares = activeSentShares.filter((s) => !revokedShareIds.has(s.shareId));
429→
430→  // 3. Re-wrap new folderKey for each remaining recipient
431→  const reWrapFailures: string[] = [];
432→  for (const share of remainingShares) {
433→    try {
434→      const recipientPubKey = hexToBytes(
435→        share.recipientPublicKey.startsWith('0x')
436→          ? share.recipientPublicKey.slice(2)
437→          : share.recipientPublicKey
438→      );
439→      const wrapped = await wrapKey(newFolderKey, recipientPubKey);
440→      await updateShareKey(share.shareId, bytesToHex(wrapped));
441→    } catch (err) {
442→      console.warn(
443→        `[share] Failed to update share key for remaining recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
444→        err
445→      );
446→      reWrapFailures.push(share.shareId);
447→    }
448→  }
449→
450→  if (reWrapFailures.length > 0) {
451→    newFolderKey.fill(0);
452→    throw new Error(
453→      `Key rotation failed: could not re-wrap key for ${reWrapFailures.length} recipient(s). ` +
454→        'Aborting to prevent inconsistent state.'
455→    );
456→  }
457→
458→  // 4. Hard-delete all revoked shares for this folder
459→  for (const revoked of revokedForFolder) {
460→    try {
461→      await completeShareRotation(revoked.shareId);
462→    } catch (err) {
463→      console.warn(`[share] Failed to complete rotation for share ${revoked.shareId}:`, err);
464→    }
465→  }
466→
467→  // 5. Invalidate the sent shares cache so next check fetches fresh state
468→  useShareStore.getState().setSentShares([]);
469→
470→  return { newFolderKey };
471→}
