  1→import { encryptFile, EncryptedFileResult } from './file-crypto.service';
  2→import { addToIpfs, AddResponse } from '../lib/api/ipfs';
  3→import { useQuotaStore } from '../stores/quota.store';
  4→import { useUploadStore } from '../stores/upload.store';
  5→import { CancelToken } from 'axios';
  6→
  7→const MAX_RETRIES = 3;
  8→const RETRY_BASE_DELAY = 1000; // 1 second
  9→
 10→export type UploadedFile = {
 11→  cid: string;
 12→  size: number;
 13→  iv: string;
 14→  wrappedKey: string;
 15→  originalName: string;
 16→  originalSize: number;
 17→  encryptionMode: 'GCM' | 'CTR';
 18→};
 19→
 20→/**
 21→ * Retry wrapper with exponential backoff.
 22→ * Does not retry cancelled operations.
 23→ */
 24→async function withRetry<T>(
 25→  fn: () => Promise<T>,
 26→  maxRetries: number = MAX_RETRIES,
 27→  baseDelay: number = RETRY_BASE_DELAY
 28→): Promise<T> {
 29→  let lastError: Error = new Error('Retry failed');
 30→
 31→  for (let attempt = 0; attempt < maxRetries; attempt++) {
 32→    try {
 33→      return await fn();
 34→    } catch (error) {
 35→      lastError = error as Error;
 36→      // Don't retry if cancelled
 37→      if ((error as Error).message === 'Upload cancelled by user') {
 38→        throw error;
 39→      }
 40→      if (attempt < maxRetries - 1) {
 41→        const delay = baseDelay * Math.pow(2, attempt);
 42→        await new Promise((resolve) => setTimeout(resolve, delay));
 43→      }
 44→    }
 45→  }
 46→
 47→  throw lastError;
 48→}
 49→
 50→/**
 51→ * Upload a single file: encrypt then upload to IPFS.
 52→ */
 53→export async function uploadFile(
 54→  file: File,
 55→  userPublicKey: Uint8Array,
 56→  onProgress?: (percent: number) => void,
 57→  cancelToken?: CancelToken
 58→): Promise<UploadedFile> {
 59→  // 1. Encrypt the file
 60→  const encrypted: EncryptedFileResult = await encryptFile(file, userPublicKey);
 61→
 62→  // 2. Upload to IPFS with retry
 63→  // Cast to ArrayBuffer for TypeScript 5.9 compatibility (Uint8Array.buffer is ArrayBufferLike)
 64→  const blob = new Blob([encrypted.ciphertext.buffer as ArrayBuffer], {
 65→    type: 'application/octet-stream',
 66→  });
 67→  const result: AddResponse = await withRetry(() => addToIpfs(blob, onProgress, cancelToken));
 68→
 69→  return {
 70→    cid: result.cid,
 71→    size: result.size,
 72→    iv: encrypted.iv,
 73→    wrappedKey: encrypted.wrappedKey,
 74→    originalName: file.name,
 75→    originalSize: encrypted.originalSize,
 76→    encryptionMode: encrypted.encryptionMode,
 77→  };
 78→}
 79→
 80→/**
 81→ * Upload multiple files sequentially.
 82→ * Pre-checks quota and tracks progress via upload store.
 83→ */
 84→export async function uploadFiles(
 85→  files: File[],
 86→  userPublicKey: Uint8Array
 87→): Promise<UploadedFile[]> {
 88→  const uploadStore = useUploadStore.getState();
 89→  const quotaStore = useQuotaStore.getState();
 90→
 91→  // Calculate total size
 92→  const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 93→
 94→  // Pre-check quota
 95→  if (!quotaStore.canUpload(totalSize)) {
 96→    throw new Error(
 97→      `Not enough space (${Math.round(quotaStore.usedBytes / 1024 / 1024)} of ${Math.round(quotaStore.limitBytes / 1024 / 1024)}MB used)`
 98→    );
 99→  }
100→
101→  uploadStore.startUpload(files.length);
102→  const results: UploadedFile[] = [];
103→
104→  try {
105→    // Sequential uploads per CONTEXT.md decision
106→    for (const file of files) {
107→      const cancelSource = useUploadStore.getState().cancelSource;
108→      if (useUploadStore.getState().status === 'cancelled') {
109→        throw new Error('Upload cancelled by user');
110→      }
111→
112→      uploadStore.setEncrypting(file.name);
113→
114→      const result = await uploadFile(
115→        file,
116→        userPublicKey,
117→        (percent) => uploadStore.setUploading(file.name, percent),
118→        cancelSource?.token
119→      );
120→
121→      results.push(result);
122→      uploadStore.fileComplete();
123→    }
124→
125→    uploadStore.setSuccess();
126→    return results;
127→  } catch (error) {
128→    const message = (error as Error).message;
129→    if (message !== 'Upload cancelled by user') {
130→      uploadStore.setError(message);
131→      console.error('Upload failed:', error);
132→    }
133→    throw error;
134→  } finally {
135→    // Refresh quota from server (authoritative source after atomic upload)
136→    await useQuotaStore.getState().fetchQuota();
137→  }
138→}
