 30→/**
 31→ * Shared hook for file preview dialogs (v2 IPNS-based).
 32→ *
 33→ * Encapsulates the IPNS-resolve-download-decrypt-blob-URL lifecycle used by
 34→ * PDF, audio, video, and image preview dialogs. Creates an object
 35→ * URL from the decrypted file content and revokes it on close.
 36→ *
 37→ * When `shareId` is provided, fetches re-wrapped file keys from share_keys
 38→ * instead of using the owner-encrypted key from file metadata.
 39→ */
 40→export function useFilePreview({
 41→  open,
 42→  item,
 43→  mimeType,
 44→  folderKey,
 45→  shareId,
 46→}: UseFilePreviewOptions): UseFilePreviewReturn {
 47→  const [loading, setLoading] = useState(false);
 48→  const [error, setError] = useState<string | null>(null);
 49→  const [objectUrl, setObjectUrl] = useState<string | null>(null);
 50→  const [decryptedData, setDecryptedData] = useState<Uint8Array | null>(null);
 51→
 52→  useEffect(() => {
 53→    if (!open || !item) {
 54→      // Clean up object URL when closing
 55→      if (objectUrl) {
 56→        URL.revokeObjectURL(objectUrl);
 57→      }
 58→      setObjectUrl(null);
 59→      setDecryptedData(null);
 60→      setError(null);
 61→      setLoading(false);
 62→      return;
 63→    }
 64→
 65→    if (!folderKey) {
 66→      setError('Folder key not available');
 67→      return;
 68→    }
 69→
 70→    let cancelled = false;
 71→    let url: string | null = null;
 72→    setLoading(true);
 73→    setError(null);
 74→
 75→    (async () => {
 76→      try {
 77→        // Use getState() to avoid stale closures in async callbacks
 78→        const auth = useAuthStore.getState();
 79→        if (!auth.vaultKeypair) {
 80→          throw new Error('No keypair available - please log in again');
 81→        }
 82→
 83→        let plaintext: Uint8Array;
 84→
 85→        if (shareId) {
 86→          // Shared file path: use re-wrapped file key from share_keys
 87→          const [{ metadata: fileMeta }, keys] = await Promise.all([
 88→            resolveFileMetadata(item.fileMetaIpnsName, folderKey!),
 89→            fetchShareKeys(shareId),
 90→          ]);
 91→
 92→          const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
 93→          if (!fileKeyRecord) {
 94→            throw new Error('No re-wrapped file key available for this file');
 95→          }
 96→
 97→          plaintext = await downloadFile(
 98→            {
 99→              cid: fileMeta.cid,
100→              iv: fileMeta.fileIv,
101→              wrappedKey: fileKeyRecord.encryptedKey,
102→              originalName: item.name,
103→              encryptionMode: fileMeta.encryptionMode,
104→            },
105→            auth.vaultKeypair.privateKey
106→          );
107→        } else {
108→          // Owner path: use file key from metadata directly
109→          plaintext = await downloadFileFromIpns({
110→            fileMetaIpnsName: item.fileMetaIpnsName,
111→            folderKey: folderKey!,
112→            privateKey: auth.vaultKeypair.privateKey,
113→            fileName: item.name,
114→          });
115→        }
116→
117→        if (cancelled) return;
118→
119→        const blob = new Blob([plaintext as BlobPart], { type: mimeType });
120→        url = URL.createObjectURL(blob);
121→
122→        setDecryptedData(plaintext);
123→        setObjectUrl(url);
124→        setLoading(false);
125→      } catch (err) {
126→        if (cancelled) return;
127→        setError(err instanceof Error ? err.message : 'Failed to load file');
128→        setLoading(false);
129→      }
130→    })();
131→
132→    return () => {
133→      cancelled = true;
134→      if (url) {
135→        URL.revokeObjectURL(url);
136→      }
137→    };
138→  }, [open, item, folderKey, mimeType, shareId]);
139→
140→  const handleDownload = useCallback(() => {
141→    if (!decryptedData || !item) return;
142→    triggerBrowserDownload(decryptedData, item.name, mimeType);
143→  }, [decryptedData, item, mimeType]);
144→
145→  return { loading, error, objectUrl, decryptedData, handleDownload };
146→}
