236→  /**
237→   * Create a new subfolder inside an existing folder.
238→   *
239→   * Generates IPNS keypair and folder key, wraps with user's public key,
240→   * adds folder entry to parent metadata, publishes parent IPNS record,
241→   * and publishes empty folder metadata for the new subfolder.
242→   *
243→   * @param parentIpnsName - IPNS name of the parent folder
244→   * @param name - Name for the new subfolder
245→   * @returns Created folder's UUID, IPNS name, folder key, and IPNS private key
246→   */
247→  async createFolder(
248→    parentIpnsName: string,
249→    name: string
250→  ): Promise<{ id: string; ipnsName: string; folderKey: Uint8Array; ipnsPrivateKey: Uint8Array }> {
251→    return this.withOperation('createFolder', async () => {
252→      const parent = this.folderTree.get(parentIpnsName);
253→      if (!parent) throw new Error('Parent folder not loaded');
254→
255→      // 1. Create subfolder (generates keys, wraps with user public key)
256→      const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
257→        await sdkCore.createSubfolder({
258→          name,
259→          userPublicKey: this.config.vaultKeypair.publicKey,
260→          teeKeys: this.config.teeKeys,
261→        });
262→
263→      // 2. Check for duplicate name
264→      if (parent.children.some((child) => child.name === name)) {
265→        throw new Error('An item with this name already exists');
266→      }
267→
268→      // 3. Add folder entry to parent's children
269→      const updatedChildren: FolderChild[] = [...parent.children, folder];
270→
271→      // 3. Update parent metadata and publish
272→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
273→        children: updatedChildren,
274→        folderKey: parent.folderKey,
275→        ipnsPrivateKey: parent.ipnsKeypair.privateKey,
276→        ipnsName: parentIpnsName,
277→        sequenceNumber: parent.sequenceNumber,
278→        ctx: this.ctx,
279→        encryptedIpnsPrivateKey: encryptedIpnsPrivateKey,
280→        keyEpoch,
281→      });
282→
283→      // 4. Update parent state
284→      parent.children = updatedChildren;
285→      parent.sequenceNumber = newSequenceNumber;
286→      parent.lastLoadedAt = Date.now();
287→      this.folderTree.set(parentIpnsName, parent);
288→
289→      // 5. Publish empty metadata for the new subfolder
290→      await sdkCore.updateFolderMetadataAndPublish({
291→        children: [],
292→        folderKey,
293→        ipnsPrivateKey,
294→        ipnsName: folder.ipnsName,
295→        sequenceNumber: 0n,
296→        ctx: this.ctx,
297→        encryptedIpnsPrivateKey,
298→        keyEpoch,
299→      });
300→
301→      // 7. Emit parent folder updated event
302→      this.emitter.emit({
303→        type: 'folder:updated',
304→        folderId: parentIpnsName,
305→        ipnsName: parentIpnsName,
306→        children: updatedChildren,
307→        sequenceNumber: newSequenceNumber,
308→      });
309→
310→      return { id: folder.id, ipnsName: folder.ipnsName, folderKey, ipnsPrivateKey };
311→    });
312→  }
