362→  /**
363→   * Move a child entry between two folders.
364→   *
365→   * Removes from source, adds to destination, publishes both IPNS records
366→   * (destination first for crash safety -- add-before-remove pattern).
367→   *
368→   * @param sourceIpnsName - IPNS name of the source folder
369→   * @param destIpnsName - IPNS name of the destination folder
370→   * @param childId - ID of the child to move
371→   */
372→  async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
373→    return this.withOperation('moveItem', async () => {
374→      const source = this.folderTree.get(sourceIpnsName);
375→      const dest = this.folderTree.get(destIpnsName);
376→      if (!source) throw new Error('Source folder not loaded');
377→      if (!dest) throw new Error('Destination folder not loaded');
378→
379→      // 1. Compute updated children for both folders (pure operation)
380→      const { updatedSourceChildren, updatedDestChildren } = sdkCore.moveItem({
381→        sourceChildren: source.children,
382→        destChildren: dest.children,
383→        childId,
384→      });
385→
386→      // 2. Publish destination first (add-before-remove for crash safety)
387→      const destResult = await sdkCore.updateFolderMetadataAndPublish({
388→        children: updatedDestChildren,
389→        folderKey: dest.folderKey,
390→        ipnsPrivateKey: dest.ipnsKeypair.privateKey,
391→        ipnsName: destIpnsName,
392→        sequenceNumber: dest.sequenceNumber,
393→        ctx: this.ctx,
394→      });
395→
396→      // 3. Publish source (remove)
397→      const sourceResult = await sdkCore.updateFolderMetadataAndPublish({
398→        children: updatedSourceChildren,
399→        folderKey: source.folderKey,
400→        ipnsPrivateKey: source.ipnsKeypair.privateKey,
401→        ipnsName: sourceIpnsName,
402→        sequenceNumber: source.sequenceNumber,
403→        ctx: this.ctx,
404→      });
405→
406→      // 4. Update internal state
407→      source.children = updatedSourceChildren;
408→      source.sequenceNumber = sourceResult.newSequenceNumber;
409→      dest.children = updatedDestChildren;
410→      dest.sequenceNumber = destResult.newSequenceNumber;
411→      this.folderTree.set(sourceIpnsName, source);
412→      this.folderTree.set(destIpnsName, dest);
413→
414→      // 5. Emit events for both folders
415→      this.emitter.emit({
416→        type: 'folder:updated',
417→        folderId: sourceIpnsName,
418→        ipnsName: sourceIpnsName,
419→        children: updatedSourceChildren,
420→        sequenceNumber: sourceResult.newSequenceNumber,
421→      });
422→      this.emitter.emit({
423→        type: 'folder:updated',
424→        folderId: destIpnsName,
425→        ipnsName: destIpnsName,
426→        children: updatedDestChildren,
427→        sequenceNumber: destResult.newSequenceNumber,
428→      });
429→    });
